export const diagnosticTrees = [
  {id:'tree-no-crank',title:'No crank, click, or slow crank',applies:['NA','NB','NC','ND'],symptoms:['silence when key is turned','single click','rapid clicks','starter turns slowly','intermittent starting'],entry:'The engine does not rotate normally when the start command is requested.',firstChecks:['Battery state of charge and terminal condition','What the symptom sounds like: silence, click, rapid clicks, or slow rotation','Battery voltage during cranking','Starter feed and ground voltage drop','Clutch or neutral input, relay, immobilizer, and start-command evidence'],branches:[{when:'Battery voltage collapses under load or terminals are loose/corroded',meaning:'The starter may be innocent. Correct battery capacity and connection first, then retest.',next:'battery-path'},{when:'Battery holds but the starter feed or ground loses significant voltage under load',meaning:'Cable, ground, connection, or fuse-link resistance is limiting current.',next:'cable-ground'},{when:'The starter receives a valid command and full voltage but does not operate',meaning:'Solenoid or starter motor fault is likely after mechanical engagement is confirmed.',next:'starter'},{when:'No start command reaches the solenoid',meaning:'Trace the switch, clutch/neutral input, relay, immobilizer, fuse, and control wiring.',next:'control-path'}],stop:'Stop if cables heat, smoke, a battery swells, or the engine may be mechanically locked.',related:['trouble-no-crank','charging-check'],facts:'A no-crank complaint is an electrical or mechanical rotation problem before it is a fuel or spark problem.',misconception:'A new starter is not a diagnosis; dirty grounds and low battery capacity commonly imitate starter failure.',unknown:'Exact voltage-drop limits and start-command logic vary by generation, market, and modification.'},
  {id:'tree-crank-no-start',title:'Cranks normally but will not start',applies:['NA','NB','NC','ND'],symptoms:['crank no start','starts then dies','no spark','no fuel pressure','flooded engine','long crank'],entry:'The engine rotates at normal speed but does not sustain combustion.',firstChecks:['Battery voltage and cranking speed','Check-engine lamp behavior and stored codes','Spark presence and timing reference','Fuel pressure, injector command, and fuel quality','Compression, valve timing, and cam/crank plausibility'],branches:[{when:'No usable spark or no ignition reference is proven',meaning:'Test power, grounds, crank/cam signals, ignition control, immobilizer boundaries, and timing—not only the named sensor.',next:'spark-reference'},{when:'Fuel pressure or injector command is missing',meaning:'Separate pump power, relay, filter, regulator, injector control, fuel contamination, and ECU authorization.',next:'fuel-path'},{when:'Spark and fuel exist but compression or cam timing is abnormal',meaning:'Move to mechanical timing, valve-train, compression, and possible internal damage.',next:'mechanical'},{when:'The engine fires briefly on a controlled test but will not run',meaning:'Check sustained fuel delivery, air metering, idle control, immobilizer behavior, and flooding without repeated starting-fluid use.',next:'sustain'}],stop:'Stop repeated cranking if fuel smell is strong, oil is fuel-diluted, the belt or chain may have failed, or mechanical damage is suspected.',related:['trouble-crank-no-start','compression-plan','timing-belt-na-nb'],facts:'An engine needs adequate rotation, correctly timed ignition, usable fuel delivery, compression, and authorization/control.',misconception:'A crankshaft-position code is evidence of a signal problem, not automatic proof that the sensor itself is bad.',unknown:'Exact fuel pressure, scan parameters, and self-test methods depend on engine and market.'},
  {id:'tree-overheat',title:'Overheats in traffic, at speed, or after shutdown',applies:['NA','NB','NC','ND'],symptoms:['temperature rises in traffic','overheats on highway','heater goes cold','coolant loss','fans do not run','hot after shutdown'],entry:'Classify the heat event before replacing cooling parts.',firstChecks:['When the temperature rises: idle, speed, load, A/C, or after shutdown','Coolant level, leak evidence, cap condition, and air in the system','Fan command and actual fan operation','Radiator temperature distribution and thermostat behavior','Combustion-gas or internal-leak evidence if external causes are excluded'],branches:[{when:'Overheats mainly while stationary or with A/C load',meaning:'Prioritize airflow, fan command, fan motor, shroud, condenser blockage, and low-speed control.',next:'airflow'},{when:'Overheats mainly at speed or under sustained load',meaning:'Prioritize coolant level, circulation, radiator restriction, thermostat, pump, cap, and internal load.',next:'circulation'},{when:'Coolant is repeatedly lost or the system pressurizes abnormally',meaning:'Find the external leak and evaluate combustion-gas or internal leakage evidence.',next:'leak'},{when:'Heater output goes cold during the event',meaning:'Low coolant, trapped air, or loss of circulation is more likely than a simple fan-only fault.',next:'air-circulation'}],stop:'Do not open a hot pressurized system. Stop driving if coolant is lost, the gauge is abnormal, steam appears, or oil pressure is in doubt.',related:['trouble-overheat','water-pump-thermostat','cooling-triage'],facts:'Cooling diagnosis depends on heat load, airflow, coolant circulation, pressure, and accurate temperature evidence.',misconception:'A larger radiator cannot correct a failed fan, trapped air, weak cap, or coolant leak.',unknown:'Gauge behavior and fan strategy differ across generation, engine, market, and ECU calibration.'},
  {id:'tree-rough-idle',title:'Rough idle, stumble, hunting, or stalling',applies:['NA','NB','NC','ND'],symptoms:['rough idle','stall at stops','surging rpm','cold-start stumble','misfire','lean code'],entry:'Determine whether the problem is air, fuel, ignition, mechanical timing, control, or low voltage.',firstChecks:['Cold versus warm behavior and accessory load','Codes, misfire counters, fuel trims, coolant temperature, throttle position','Unmetered air, PCV, brake-booster, and intake leaks','Spark plugs, coils/wires, fuel pressure, and injector clues','Battery voltage, grounds, compression, and cam timing when evidence points mechanical'],branches:[{when:'Fuel trims are strongly positive and smoke reveals a leak',meaning:'Repair unmetered-air entry before replacing oxygen or airflow sensors.',next:'intake-leak'},{when:'One cylinder shows repeated misfire and ignition or injector evidence follows it',meaning:'Swap-test or measure the component, then confirm wiring and mechanical health.',next:'cylinder'},{when:'All cylinders change with coolant temperature or load data',meaning:'Check sensor plausibility, idle control, throttle, fuel delivery, and low voltage.',next:'control'},{when:'Misfire follows compression or timing evidence',meaning:'Move to valve clearance, timing, leak-down, and mechanical inspection.',next:'mechanical'}],stop:'Avoid extended operation if the check-engine lamp flashes, the catalyst may overheat, or oil is fuel-diluted.',related:['trouble-rough-idle','smoke-test-intake','spark-plug-service'],facts:'Fuel trims and misfire data are clues that must be paired with air, ignition, fuel, and mechanical tests.',misconception:'Cleaning a throttle body is not a universal repair for rough idle.',unknown:'Normal trim and idle values vary with generation, engine, temperature, and modifications.'},
  {id:'tree-charge-drain',title:'Battery goes flat or charging warning appears',applies:['NA','NB','NC','ND'],symptoms:['dead battery','battery light','dim lights','voltage unstable','battery dies parked','accessory drain'],entry:'Separate battery health, charging output, voltage loss, and parasitic draw.',firstChecks:['Battery health and state of charge','Charging voltage under load and at operating temperature','Positive and ground-side voltage drop','Belt, alternator, main fuse, and connector condition','Sleep current after the vehicle reaches its normal module state'],branches:[{when:'Battery fails a health test or cannot hold charge',meaning:'Resolve battery capacity before condemning the alternator or chasing a draw.',next:'battery'},{when:'Charging output is low or unstable under load',meaning:'Test belt drive, alternator, grounds, main fuse, control wiring, and voltage drop.',next:'charge-path'},{when:'Charging is normal but the battery dies parked',meaning:'Perform a controlled parasitic-draw test without waking the modules repeatedly.',next:'parasitic'},{when:'Voltage is normal but warning lamps or accessories behave oddly',meaning:'Check grounds, low-voltage history, network/module faults, and aftermarket wiring.',next:'low-voltage'}],stop:'Do not continue driving if the battery warning is on, the belt is failing, or voltage is high enough to damage modules.',related:['trouble-charge','trouble-parasitic','charging-check','aftermarket-wiring'],facts:'A charging number at one moment does not prove battery health or correct sleep current.',misconception:'Replacing the alternator is not the correct first response to every dead battery.',unknown:'Sleep-current expectations and module wake behavior differ by generation and accessories.'},
  {id:'tree-brake-steering',title:'Brake pull, soft pedal, vibration, or steering wander',applies:['NA','NB','NC','ND'],symptoms:['pulls under braking','soft pedal','crooked steering wheel','wheel shake','uneven tire wear','wanders'],entry:'Separate tire, wheel, brake, hydraulic, bearing, bushing, and alignment causes before adjustment.',firstChecks:['Tire pressure, size, construction, wear, and wheel condition','Fluid level, leaks, hose condition, pad wear, and caliper movement','Wheel-bearing, ball-joint, tie-rod, and bushing play','Rotor runout or temperature difference after a controlled test','Four-wheel alignment measurements after worn parts are corrected'],branches:[{when:'Pull is stronger only under braking and one corner runs hot',meaning:'Prioritize caliper, hose, pad, rotor, or bearing drag.',next:'brake-drag'},{when:'Pedal is soft or changes after pumping',meaning:'Check air, fluid, hose expansion, pad knockback, leaks, and master-cylinder behavior.',next:'hydraulic'},{when:'Pull or drift occurs at steady speed with uneven tire wear',meaning:'Check tire conicity, road crown, steering geometry, and alignment.',next:'alignment'},{when:'Vibration follows speed rather than braking',meaning:'Check tire/wheel balance, hub, bearing, axle, and driveline sources.',next:'speed-vibration'}],stop:'Do not drive if the pedal is sinking, a hose leaks, a wheel is loose, or steering play is severe.',related:['trouble-brake-pull','brake-pad-rotor-service','brake-fluid-bleed','hub-bearing-service'],facts:'Alignment cannot correct a seized brake, loose joint, damaged tire, or bent wheel.',misconception:'A crooked steering wheel is not automatically an alignment-only problem.',unknown:'Target alignment depends on generation, tire, ride height, use, and driver preference.'},
  {id:'tree-nvh',title:'Noise, vibration, harshness, clunk, or hum',applies:['NA','NB','NC','ND'],symptoms:['wheel hum','driveline vibration','clunk over bumps','engine vibration','gear whine','exhaust rattle'],entry:'Find the variable that changes the symptom: road speed, engine RPM, gear, throttle, steering, braking, or bumps.',firstChecks:['Does it follow road speed or engine speed?','Does load, coast, gear, or steering change it?','Tire, wheel, hub, bearing, mount, axle, driveshaft, exhaust, and shield inspection','Fastener torque, clearance, fluid leak, and contact evidence','Repeatable road test with one variable changed at a time'],branches:[{when:'Noise follows road speed and cornering changes it',meaning:'Prioritize tire, wheel, hub, and bearing evidence.',next:'wheel-speed'},{when:'Vibration follows engine RPM while stationary',meaning:'Prioritize engine mount, accessory, ignition, fueling, and engine-balance evidence.',next:'engine-speed'},{when:'Vibration changes with throttle or gear',meaning:'Prioritize mounts, driveshaft, PPF, axle, differential, and transmission evidence.',next:'load'},{when:'Clunk appears on bumps or steering input',meaning:'Inspect joints, bushings, sway links, rack mounts, top mounts, and loose hardware.',next:'chassis'}],stop:'Stop if the noise is accompanied by looseness, fluid loss, heat, tire damage, or a rapidly worsening vibration.',related:['trouble-noise-vibration','hub-bearing-service','transmission-fluid-service','differential-fluid-service'],facts:'The change condition is often more diagnostic than the noise description.',misconception:'Replacing a wheel bearing based only on a generic humming sound creates expensive misdiagnosis.',unknown:'Noise transfer through the lightweight chassis can make the source appear several feet from the failed part.'},
  {id:'tree-water-leak',title:'Water leak, wet carpet, damp trunk, or soft-top issue',applies:['NA','NB','NC','ND'],symptoms:['wet carpet','water in trunk','damp seat-belt tower','mildew','top leak','window or seal leak'],entry:'Map the wettest point and reproduce one possible entry path at a time.',firstChecks:['Dry interior and locate the highest wet point','Top drains, cowl, windshield, trunk seals, lamps, grommets, door membranes, and seams','Parking angle and weather direction','Low-pressure water test by zone','Drain flow and drying condition after repair'],branches:[{when:'Water appears near the top or seat-belt tower',meaning:'Inspect roof seams, header, side seals, drain paths, and adjustment before sealing anything.',next:'top-path'},{when:'Water pools in the footwell or cowl area',meaning:'Inspect cowl drains, windshield path, firewall grommets, and door membrane.',next:'cowl-path'},{when:'Trunk or spare-wheel area is wet',meaning:'Inspect trunk seal, lamps, antenna, drains, seams, and rear body openings.',next:'trunk-path'},{when:'The leak is not repeatable',meaning:'Dry completely, use one-zone low-pressure testing, and avoid high-pressure water that creates false paths.',next:'controlled-test'}],stop:'Dry electrical modules and saturated insulation promptly. Do not trap moisture under sealant or continue driving if visibility or electrical safety is affected.',related:['trouble-water-leak','soft-top-drains'],facts:'Water travels through seams, cavities, insulation, and trim before appearing at the lowest visible point.',misconception:'Sealing the wettest carpet point is not the same as repairing the entry path.',unknown:'Top and drain routing varies significantly across NA/NB, NC PRHT, and ND RF/soft-top configurations.'},
  {id:'tree-abs-dsc',title:'ABS, DSC, traction, or brake warning light',applies:['NA','NB','NC','ND'],symptoms:['ABS light','DSC light','traction-control warning','wheel-speed fault','brake warning','stability-control intervention'],entry:'Record codes and module data before clearing anything or replacing a sensor.',firstChecks:['All module codes and freeze-frame data','Battery voltage and charging history','Tire size, pressure, wear, and wheel-bearing play','Wheel-speed live data and sensor wiring','Brake fluid, hydraulic condition, tone ring, and hub fitment'],branches:[{when:'One wheel-speed signal drops out or disagrees',meaning:'Inspect sensor, wiring, tone ring, hub, bearing, tire, and connector before replacing the sensor.',next:'wheel-speed'},{when:'Multiple modules report low voltage or communication faults',meaning:'Resolve battery, charging, grounds, fuses, and network power before chasing individual codes.',next:'network'},{when:'The warning follows a brake or suspension modification',meaning:'Verify wheel speed, brake package, alignment, sensor routing, and calibration requirements.',next:'modification'},{when:'The warning is accompanied by a sinking pedal or hydraulic leak',meaning:'Treat the mechanical brake fault as the priority and stop driving.',next:'hydraulic'}],stop:'Do not treat disabled stability or ABS systems as normal. Escalate brake, SRS, or network faults when the required equipment or procedure is unavailable.',related:['abs-dsc-warning','scan-code-workflow','hub-bearing-service'],facts:'A code identifies a monitored circuit or condition, not automatically the component that should be replaced.',misconception:'Clearing a warning light is not verification of a repair.',unknown:'Module access, calibration, and test requirements vary across generation, market, trim, and scan-tool capability.'}
];

export const manualSearchIndex = procedures.map(p => ({id:p.id, text:[p.title,p.system,p.book,p.symptoms,...p.tags,...p.applies].join(' ').toLowerCase()}));
